package dev.aragonite.powersync.client;
import android.content.Context;import android.os.Environment;import android.util.AtomicFile;import android.util.Base64;import org.json.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
final class TransitionController {
 final NativeBridge nativeIO;final PrivateState state;final Context context;
 TransitionController(Context c){context=c.getApplicationContext();nativeIO=new NativeBridge(context);state=new PrivateState(context);}
 private File marker(){return new File(Environment.getExternalStorageDirectory(),"onyx_test_server");}
 private void storage()throws IOException {if(!Environment.isExternalStorageManager())throw new IOException("Grant All Files Access before configuring or restoring native endpoints");}
 private void phase(JSONObject journal,String phase)throws Exception {journal.put("phase",phase).put("updatedAt",System.currentTimeMillis());state.write("transition",journal);}
 JSONObject status()throws Exception {nativeIO.compatible();JSONObject j=state.read("transition"),c=nativeIO.read(NativeBridge.CLUSTER);JSONObject a=nativeIO.account();return new JSONObject().put("clusterId",c.getString("curClusterId")).put("accountLoggedIn",a.optBoolean("loggedIn")).put("flags",nativeIO.flags()).put("phase",j==null?"not_configured":j.getString("phase")).put("hasBaseline",state.read("baseline")!=null).put("applicationVerified",false).put("allFilesAccess",Environment.isExternalStorageManager());}
 JSONObject enroll(String base,String code)throws Exception {nativeIO.compatible();JSONObject journal=state.read("transition");if(journal!=null&&!java.util.Set.of("restored").contains(journal.optString("phase")))throw new IOException("Return to the previous server before enrolling again");String install=state.installationId();String id=nativeIO.read(NativeBridge.SYSTEM).optString("deviceUniqueId","");if(id.isEmpty())id=android.provider.Settings.Secure.getString(context.getContentResolver(),android.provider.Settings.Secure.ANDROID_ID);if(id==null||id.isEmpty())throw new IOException("Native device identity unavailable");JSONObject originalAccount=nativeIO.account();String owner=originalAccount.optBoolean("loggedIn")?originalAccount.getString("uid"):"";JSONObject p=EndpointProfile.validate(base,ServerClient.redeem(base,code,install,id,owner));if(!owner.isEmpty()&&!owner.equals(p.getString("nativeUid")))throw new IOException("Server did not preserve your BOOX library identity; configuration has not changed");p.put("enrollmentAccount",originalAccount);state.write("profile",p);return new JSONObject().put("serverURL",base).put("libraryId",p.getString("libraryId")).put("ready",true);}
 void connect(boolean notes,boolean reader)throws Exception {storage();nativeIO.compatible();JSONObject profile=state.read("profile");if(profile==null)throw new IOException("Enroll this device first");JSONObject journal=state.read("transition");if(journal!=null&&!java.util.Set.of("restored").contains(journal.optString("phase")))throw new IOException("A transition already exists; use Return to previous server");JSONObject enrollmentAccount=profile.optJSONObject("enrollmentAccount");if(enrollmentAccount==null)throw new IOException("Enroll again to preserve your existing BOOX library");if(!NativeBridge.canonical(enrollmentAccount).equals(NativeBridge.canonical(nativeIO.account())))throw new IOException("Your BOOX account changed after enrollment; enroll again before connecting");JSONObject current=nativeIO.read(NativeBridge.CLUSTER);String id=profile.getJSONObject("cluster").getString("clusterId");if(current.getJSONObject("clusterMap").has(id))throw new IOException("Target cluster already exists; inspect instead of overwriting");byte[] markerBytes=marker().exists()?Files.readAllBytes(marker().toPath()):null;if(markerBytes!=null&&markerBytes.length>1048576)throw new IOException("Native server marker exceeds bound");JSONArray markers=markerBytes==null||markerBytes.length==0?new JSONArray():new JSONArray(new String(markerBytes,StandardCharsets.UTF_8));for(int i=0;i<markers.length();i++)if(id.equals(markers.getJSONObject(i).optString("serverId")))throw new IOException("Marker already contains this cluster");JSONObject before=new JSONObject().put("cluster",current).put("flags",nativeIO.flags()).put("account",nativeIO.account()).put("accountCache",new NativeAccountBackup(nativeIO).capture(profile.getString("nativeUid"))).put("fingerprint",nativeIO.fingerprint()).put("catalog",nativeIO.catalog()).put("marker",markerBytes==null?JSONObject.NULL:Base64.encodeToString(markerBytes,Base64.NO_WRAP));state.write("baseline",before);journal=new JSONObject().put("phase","prepared").put("clusterId",id).put("nativeUid",profile.getString("nativeUid"));state.write("transition",journal);
  try{phase(journal,"pause_requested");nativeIO.flags(new JSONObject().put("notes","false").put("reader","false"));phase(journal,"paused");JSONObject map=nativeIO.read(NativeBridge.CLUSTER);map.getJSONObject("clusterMap").put(id,profile.getJSONObject("cluster"));if(map.has("clusterMapSize"))map.put("clusterMapSize",map.getJSONObject("clusterMap").length());state.write("installed-cluster",profile.getJSONObject("cluster"));phase(journal,"configure_requested");nativeIO.write(NativeBridge.CLUSTER,map);markers.put(EndpointProfile.marker(profile));byte[] installedBytes=markers.toString().getBytes(StandardCharsets.UTF_8);state.write("installed-marker",new JSONObject().put("sha256",NativeBridge.hex(java.security.MessageDigest.getInstance("SHA-256").digest(installedBytes))));writeMarker(installedBytes);phase(journal,"configured");phase(journal,"refresh_requested");nativeIO.updateClusters();JSONObject refreshedDefinition=nativeIO.read(NativeBridge.CLUSTER).getJSONObject("clusterMap").getJSONObject(id);if(!NativeBridge.canonical(refreshedDefinition.getJSONObject("clusterHost")).equals(NativeBridge.canonical(profile.getJSONObject("cluster").getJSONObject("clusterHost"))))throw new IOException("Native refresh replaced the enrolled endpoints");state.write("installed-cluster",refreshedDefinition);phase(journal,"refreshed");phase(journal,"switch_requested");nativeIO.switchCluster(id);phase(journal,"switched");nativeIO.repairMissingCatalog(before.getJSONArray("catalog"));if(!before.getString("fingerprint").equals(nativeIO.fingerprint()))throw new IOException("Native library changed during transition; synchronization remains paused");phase(journal,"login_requested");new NativeAccountBackup(nativeIO).verifyBeforeLogin(before.getJSONArray("accountCache"),profile.getString("nativeUid"));nativeIO.login(profile.getJSONObject("account").getString("account"),profile.getJSONObject("account").getString("code"),false);JSONObject account=nativeIO.account();if(!account.optBoolean("loggedIn")||!profile.getString("nativeUid").equals(account.optString("uid")))throw new IOException("Native account mapping differs");nativeIO.repairMissingCatalog(before.getJSONArray("catalog"));if(!before.getString("fingerprint").equals(nativeIO.fingerprint()))throw new IOException("Native library changed during sign-in; synchronization remains paused");phase(journal,"authenticated");nativeIO.flags(new JSONObject().put("notes",Boolean.toString(notes)).put("reader",Boolean.toString(reader)));phase(journal,"active");}catch(Exception e){journal.put("failure","Transition interrupted; baseline preserved");phase(journal,"failed");throw e;}}
 private void writeMarker(byte[] raw)throws Exception {AtomicFile f=new AtomicFile(marker());FileOutputStream out=f.startWrite();try{out.write(raw);out.getFD().sync();f.finishWrite(out);}catch(Exception e){f.failWrite(out);throw e;}}
 void restore()throws Exception {nativeIO.compatible();storage();JSONObject before=state.read("baseline"),journal=state.read("transition");if(before==null||journal==null)throw new IOException("No saved previous configuration");if("restored".equals(journal.optString("phase")))return;String custom=journal.getString("clusterId");String original=before.getJSONObject("cluster").getString("curClusterId");JSONObject live=nativeIO.read(NativeBridge.CLUSTER);String selected=live.getString("curClusterId");if(!selected.equals(custom)&&!selected.equals(original))throw new IOException("Another server is selected; inspect before restoration");JSONObject installed=state.read("installed-cluster");JSONObject entry=live.getJSONObject("clusterMap").optJSONObject(custom);if(entry!=null&&installed!=null&&!NativeBridge.canonical(entry).equals(NativeBridge.canonical(installed)))throw new IOException("Custom endpoint changed outside PowerSync; inspect before restoration");JSONObject installedMarker=state.read("installed-marker");if(installedMarker!=null){byte[] currentMarker=marker().isFile()?Files.readAllBytes(marker().toPath()):null;byte[] previousMarker=before.isNull("marker")?null:Base64.decode(before.getString("marker"),Base64.DEFAULT);boolean originalMarker=java.util.Arrays.equals(currentMarker,previousMarker);boolean ownedMarker=currentMarker!=null&&installedMarker.getString("sha256").equals(NativeBridge.hex(java.security.MessageDigest.getInstance("SHA-256").digest(currentMarker)));if(!originalMarker&&!ownedMarker)throw new IOException("Native marker changed outside PowerSync; preserve it before restoration");}
  phase(journal,"restore_requested");nativeIO.flags(new JSONObject().put("notes","false").put("reader","false"));if(!live.getJSONObject("clusterMap").has(original)){live.getJSONObject("clusterMap").put(original,before.getJSONObject("cluster").getJSONObject("clusterMap").get(original));nativeIO.write(NativeBridge.CLUSTER,live);}if(!original.equals(selected))nativeIO.switchCluster(original);JSONObject map=nativeIO.read(NativeBridge.CLUSTER);map.getJSONObject("clusterMap").remove(custom);map.put("curClusterId",original);if(map.has("clusterMapSize"))map.put("clusterMapSize",map.getJSONObject("clusterMap").length());nativeIO.write(NativeBridge.CLUSTER,map);
  if(installedMarker!=null){if(before.isNull("marker")){new AtomicFile(marker()).delete();if(marker().exists())throw new IOException("Cannot remove PowerSync marker");}else writeMarker(Base64.decode(before.getString("marker"),Base64.DEFAULT));}
  nativeIO.repairMissingCatalog(before.getJSONArray("catalog"));boolean accountRestored=before.has("accountCache")?new NativeAccountBackup(nativeIO).restore(before.getJSONObject("account"),before.getJSONArray("accountCache"),journal.getString("nativeUid"),custom):nativeIO.restoreAccount(before.getJSONObject("account"),journal.getString("nativeUid"));JSONObject refreshed=nativeIO.read(NativeBridge.CLUSTER);refreshed.getJSONObject("clusterMap").remove(custom);if(refreshed.has("clusterMapSize"))refreshed.put("clusterMapSize",refreshed.getJSONObject("clusterMap").length());nativeIO.write(NativeBridge.CLUSTER,refreshed);nativeIO.repairMissingCatalog(before.getJSONArray("catalog"));nativeIO.flags(accountRestored?before.getJSONObject("flags"):new JSONObject().put("notes","false").put("reader","false"));phase(journal,accountRestored?"restored":"needs_signin");}
 JSONObject recoveryStatus()throws Exception {JSONObject p=state.read("profile");if(p==null)throw new IOException("Enroll a server first");return ServerClient.request(p.getString("serverURL")+"/api/v1/boox/device/status","GET",null,p.getString("companionToken"));}
 private JSONObject audioProfile()throws Exception {
  storage();nativeIO.compatible();JSONObject p=state.read("profile"),j=state.read("transition");
  if(p==null||j==null||!"active".equals(j.optString("phase")))throw new IOException("Connect to your enrolled server before recovering audio");
  JSONObject a=nativeIO.account();
  if(!a.optBoolean("loggedIn")||!p.getString("nativeUid").equals(a.optString("uid"))||!p.getJSONObject("cluster").getString("clusterId").equals(nativeIO.read(NativeBridge.CLUSTER).getString("curClusterId")))throw new IOException("Native account or selected server changed");
  return p;
 }
 JSONArray audioRecoveries()throws Exception {
  JSONObject p=audioProfile();JSONArray all=new JSONArray();String after="";
  do {JSONObject reply=ServerClient.request(p.getString("serverURL")+"/api/v1/boox/device/audio-recovery?after="+after,"GET",null,p.getString("companionToken"));
   if(!p.getString("nativeUid").equals(reply.getString("nativeUid")))throw new IOException("Audio library identity differs");
   JSONArray items=reply.getJSONArray("items");for(int i=0;i<items.length();i++)all.put(items.getJSONObject(i));
   String next=reply.getString("next");if(!next.isEmpty()){java.util.UUID.fromString(next);if(next.compareTo(after)<=0)throw new IOException("Invalid audio recovery cursor");}after=next;
   if(all.length()>1000)throw new IOException("Too many audio repairs; review this library on the server");
  }while(!after.isEmpty());return all;
 }
 AudioCacheRepair audioPacket(String id)throws Exception {
  java.util.UUID.fromString(id);JSONObject p=audioProfile();
  AudioCacheRepair repair=new AudioCacheRepair(ServerClient.request(p.getString("serverURL")+"/api/v1/boox/device/audio-recovery?operation="+id,"GET",null,p.getString("companionToken"),24*1024*1024),p.getString("nativeUid"));
  try(android.database.Cursor c=context.getContentResolver().query(android.net.Uri.parse("content://com.onyx.android.sdk.note.ContentProvider/NoteModel"),new String[]{"uniqueId"},"uniqueId=? AND userId=? AND type=1 AND status=1",new String[]{repair.document,repair.uid},null)){
   if(c==null||c.getCount()!=1)throw new IOException("The active notebook is not available in this device’s library");
  }
  return repair;
 }
 String inspectAudio(AudioCacheRepair repair)throws Exception {return repair.inspect(Environment.getExternalStorageDirectory().toPath());}
 void repairAudio(AudioCacheRepair selected)throws Exception {
  AudioCacheRepair current=audioPacket(selected.operation);
  if(!current.sha.equals(selected.sha)||!current.damagedSHA.equals(selected.damagedSHA))throw new IOException("Server repair changed; review it again");
  current.apply(Environment.getExternalStorageDirectory().toPath(),new File(context.getFilesDir(),"audio-recovery-backups").toPath());
 }

}
